<?php use App\Helpers\{View,Csrf};?><div class="admin-head"><div><span class="eyebrow">FIDELIZACIÓN</span><h1>Recompensas</h1></div><a href="/admin">← Panel</a></div><div class="two-col"><form class="panel" method="post" action="/admin/rewards"><?=Csrf::field()?><h2>Nueva recompensa</h2><label>Nombre<input name="name" placeholder="10% de descuento" required></label><label>Puntos requeridos<input type="number" name="points_required" min="1" required></label><label>Porcentaje de descuento<input type="number" step="0.01" min="0" max="100" name="discount_percent" required></label><button class="primary">Guardar</button></form><section class="panel"><h2>Recompensas</h2><?php foreach($rewards as $r):?><div class="rewardrow"><div><b><?=View::e($r['name'])?></b><small><?=$r['points_required']?> pts · <?=$r['discount_percent']?>%</small></div><span class="status"><?=View::e($r['status'])?></span><form method="post" action="/admin/rewards/<?=$r['id']?>/toggle"><?=Csrf::field()?><button class="linkbtn">Cambiar</button></form></div><?php endforeach;?></section></div>